"""Connect model with mcp tools in Python
# Run this python script
> pip install openai-agents==0.*
> python <this-script-path>.py
"""
import asyncio
import json
import logging
import os
import sys
from typing import Any

from agents import Agent, AgentOutputSchemaBase, ModelSettings, OpenAIChatCompletionsModel, Runner, set_tracing_disabled
from agents.mcp import MCPServerSse, MCPServerStdio, MCPServerStreamableHttp

from openai import AsyncOpenAI

async def main():
    # To authenticate with the model you will need to generate a personal access token (PAT) in your GitHub settings.
    # Create your PAT token by following instructions here: https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens
    openaiClient = AsyncOpenAI(
        base_url = "https://models.github.ai/inference",
        api_key = os.environ["GITHUB_TOKEN"],
        default_query = {
            "api-version": "2024-08-01-preview",
        },
    )

    # init MCP servers
    servers = [
        MCPServerStdio(
            params = {
                "command": "npx",
                "args": [
                    "-y",
                    "@playwright/mcp@latest",
                ],
                "env": {
                }
            },
            name = "aitk-playwright-example",
            client_session_timeout_seconds = 30,
        ),
    ]

    # setup logger
    logger = logging.getLogger("openai.agents")
    logger.setLevel(logging.DEBUG)
    logHandler = logging.StreamHandler(sys.stdout)
    logHandler.setFormatter(logging.Formatter('[Agent Log]: %(message)s'))
    logger.addHandler(logHandler)
    set_tracing_disabled(True)

    agent = Agent(
        name = "agent",
        instructions = "You are a web exploration assistant that can navigate to websites, take screenshots, and provide summaries of web content. You'll help users explore the web by visiting sites and extracting useful information.",
        mcp_servers = servers,
        model = OpenAIChatCompletionsModel("openai/gpt-4.1", openaiClient),
        model_settings = ModelSettings(
            temperature = 1,
            top_p = 1,
            reasoning = {
            },
        ),
        tools = [
        ],
    )

    try:
        for server in servers:
            await server.connect()
        result = await Runner.run(
            agent,
            [
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": "Please navigate to https://www.example.com and perform the following tasks:\n1. Take a screenshot of the main page\n2. Extract the main heading and purpose of the website\n3. Provide a brief summary of what the website is all about (2-3 sentences)",
                        },
                    ],
                },
                {
                    "id": "",
                    "type": "message",
                    "role": "assistant",
                    "status": "completed",
                    "content": [
                        {
                            "type": "output_text",
                            "text": "[{\"type\":\"text\",\"text\":\"### Ran Playwright code\\nawait page.goto('https://www.example.com');\\n\\n### New console messages\\n- [ERROR] Failed to load resource: the server responded with a status of 404 () @ https://www.example....\\n\\n### Page state\\n- Page URL: https://www.example.com/\\n- Page Title: Example Domain\\n- Page Snapshot:\\n```yaml\\n- generic [ref=e2]:\\n  - heading \\\"Example Domain\\\" [level=1] [ref=e3]\\n  - paragraph [ref=e4]: This domain is for use in documentation examples without needing permission. Avoid use in operations.\\n  - paragraph [ref=e5]:\\n    - link \\\"Learn more\\\" [ref=e6] [cursor=pointer]:\\n      - /url: https://iana.org/domains/example\\n```\\n\"}]",
                            "annotations": [],
                        },
                    ],
                },
                {
                    "id": "",
                    "type": "message",
                    "role": "assistant",
                    "status": "completed",
                    "content": [
                        {
                            "type": "output_text",
                            "text": "[{\"type\":\"text\",\"text\":\"### Ran Playwright code\\n// Screenshot viewport and save it as C:\\\\Users\\\\fesio\\\\AppData\\\\Local\\\\Temp\\\\playwright-mcp-output\\\\1767188001473\\\\example-main-page.png\\nawait page.screenshot({\\nscale: 'css',\\n  type: 'png'\\n});\\n\\n### Files\\n- [Screenshot of viewport](C:\\\\Users\\\\fesio\\\\AppData\\\\Local\\\\Temp\\\\playwright-mcp-output\\\\1767188001473\\\\example-main-page.png)\\n\"},{\"type\":\"image\",\"mimeType\":\"image/png\",\"data\":\"\"}]",
                            "annotations": [],
                        },
                    ],
                },
            ]
        )
        print("")
        print("[Model Response] " + str(result.final_output))
    except Exception as e:
        print(f"\nError: {str(e)}")
    finally:
        for server in servers:
            await server.cleanup()

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except asyncio.exceptions.CancelledError:
        # ignore cleanup cancel error
        pass